"""UI fixture is generated by real component HTTP handlers, not copied DTOs."""
import importlib.util
import json
from pathlib import Path
import uuid

ROOT = Path(__file__).resolve().parents[1]
SPEC = importlib.util.spec_from_file_location('export_components_wire_fixture',
                                            ROOT / 'scripts/export_components_wire.py')
EXPORT = importlib.util.module_from_spec(SPEC)
SPEC.loader.exec_module(EXPORT)


def test_tracked_fixture_matches_actual_api_bytes():
    assert EXPORT.FIXTURE.read_bytes() == EXPORT.encoded_fixture().encode('utf-8')


def test_repeatable_without_global_uuid_or_clock_mutation():
    original_uuid = uuid.uuid4
    original_module_uuid = EXPORT.components.uuid
    original_datetime = EXPORT.components.datetime
    first = EXPORT.fixture_document()
    assert first == EXPORT.fixture_document()
    assert uuid.uuid4 is original_uuid
    assert EXPORT.components.uuid is original_module_uuid
    assert EXPORT.components.datetime is original_datetime
    assert first['list']['body'] == {'items': [first['single']['body']], 'next_after': None}
    item = first['single']['body']
    assert item['id'] == EXPORT.COMPONENT_ID and item['project'] == EXPORT.PROJECT
    assert item['created_by'] == 'human:1' and item['revision'] == 1
    assert item['created_at'] == item['updated_at'] == EXPORT.NOW.isoformat()
    assert first['conflict']['status'] == 409
    assert first['forbidden']['status'] == 403
    assert first['validation'] == {'status': 422, 'body': {'detail': {'code': 'invalid_input'}}}
    assert all(set(first[name]['body']) == {'detail'} for name in ('conflict', 'forbidden', 'validation'))


def test_cli_check_detects_drift_without_overwrite(monkeypatch, tmp_path):
    fixture = tmp_path / 'wire.json'
    fixture.write_text('{"stale":true}\n')
    monkeypatch.setattr(EXPORT, 'FIXTURE', fixture)
    monkeypatch.setattr('sys.argv', ['export_components_wire.py', '--check'])
    assert EXPORT.main() == 1
    assert json.loads(fixture.read_text()) == {'stale': True}


def test_cli_write_and_check_match(monkeypatch, tmp_path):
    fixture = tmp_path / 'fixtures/wire.json'
    monkeypatch.setattr(EXPORT, 'FIXTURE', fixture)
    monkeypatch.setattr('sys.argv', ['export_components_wire.py', '--write'])
    assert EXPORT.main() == 0
    assert fixture.read_bytes() == EXPORT.encoded_fixture().encode('utf-8')
    monkeypatch.setattr('sys.argv', ['export_components_wire.py', '--check'])
    assert EXPORT.main() == 0
